pub fn replace_chars(s: &[char], old: char, new: char) -> Vec<char> {
    // Allocate the exact output size; we never mutate `s`.
    let mut result = Vec::with_capacity(s.len());

    for &ch in s {
        if ch == old {
            result.push(new);
        } else {
            result.push(ch);
        }
    }

    debug_assert_eq!(result.len(), s.len());
    result
}